const cvTexto = $json.CV_Texto || '';
let cvAnonimizado = cvTexto;
cvAnonimizado = cvAnonimizado.replace(/\b\d{2}[.,]?\d{3}[.,]?\d{3}\b/g, '[DNI OCULTO]');
cvAnonimizado = cvAnonimizado.replace(/\b(0?[1-9]|[12][0-9]|3[01])[\/\-](0?[1-9]|1[0-2])[\/\-](19|20)\d{2}\b/g, '[FECHA OCULTA]');
cvAnonimizado = cvAnonimizado.replace(/\b(19|20)\d{2}\b(?=.{0,15}(anios|años|edad))/gi, '[EDAD OCULTA]');
cvAnonimizado = cvAnonimizado.replace(/\b(soltero|soltera|casado|casada|divorciado|divorciada)\b/gi, '[ESTADO CIVIL OCULTO]');
const nombre = $('Formulario - Postulacion').item.json.Nombre_y_Apellido;
const emailCandidato = $('Formulario - Postulacion').item.json.Email;
const telefono = $('Formulario - Postulacion').item.json.Telefono;
const puesto = $('Formulario - Postulacion').item.json.Puesto;
return { json: { Name: nombre, Email: emailCandidato, Phone: telefono, Position: puesto, Drive_Link: $json.Drive_Link, CV_Anonymized: cvAnonimizado } };

